// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address adr, bytes memory data) public {
        vm.assume(adr != address(0));
        vm.assume(adr != address(c));
        vm.assume(adr != address(this));
        vm.assume(adr != address(vm));
        uint256 sentValue = 1 ether;
        vm.deal(address(c), 10 ether);
        vm.deal(c.Owner(), 10 ether);
        uint256 initialBalance = address(c).balance;
        vm.startPrank(c.Owner());
        c.Command{value: sentValue}(adr, data);
        vm.stopPrank();
        uint256 finalBalance = address(c).balance;
        assertTrue(finalBalance <= initialBalance);
    }
}
